      e.preventDefault();
      setMessage('');
      setIsError(false);
      setLoading(true);

      try {
         const { data } = await axiosClient.post('/verify-email-exists', { email });
         setAccountInfo(data.accountInfo);
         setVerificationStep(true);
         setIsError(false);
      } catch (error) {
         setMessage(error.response?.data?.message || 'Email not found. Please check and try again.');
