import React, { useState } from "react";
import { Link } from "react-router-dom";
import axiosClient from "@api/axios";
import { useStateContext } from "@context/ContextProvider";
import Footer from "@components/Footer";
import { FaEye, FaEyeSlash } from "react-icons/fa";
import { Loader as RsuiteLoader } from "rsuite";
import "rsuite/dist/rsuite.min.css";
import Bulb from "@components/Bulb";
import logo from "@images/AceLogo.png";
import AnimatedBackground from "../components/AnimatedBackground";
import { motion } from "framer-motion";
import ErrorMessage from "@components/ErrorMessage";

// Constants moved outside component
const INPUT_CLASS = "w-full px-4 py-3 text-gray-900 transition-all duration-200 border border-gray-200 rounded-lg focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 hover:border-blue-200";

const ANIMATIONS = {
   container: {
      initial: { opacity: 0, y: 20 },
      animate: { opacity: 1, y: 0 }
   },
   logo: {
      initial: { scale: 0.9 },
      animate: { scale: 1 }
   }
};

export default function Login() {
   const { setCurrentUser, setUserToken } = useStateContext();

   // Form state
   const [formData, setFormData] = useState({
      login: "",
      password: "",
      keepSignedIn: false
   });

   // UI state
   const [uiState, setUiState] = useState({
      showPassword: false,
      loading: false,
      error: ""
   });

   // Handlers
   const handleInputChange = (field) => (ev) => {
      setFormData(prev => ({
         ...prev,
         [field]: ev.target.type === 'checkbox' ? ev.target.checked : ev.target.value
      }));
   };

   const toggleShowPassword = () => {
      setUiState(prev => ({ ...prev, showPassword: !prev.showPassword }));
   };

   const clearError = () => {
      setUiState(prev => ({ ...prev, error: "" }));
   };

   const setLoading = (loading) => {
      setUiState(prev => ({ ...prev, loading }));
   };

   const setError = (error) => {
      setUiState(prev => ({ ...prev, error }));
   };

   // Extract error handling logic
   const handleLoginError = (error) => {
      let errorMessage = "Login or password is incorrect";

      if (error.response) {
         if (error.response.status === 401) {
            errorMessage = "Login or password is incorrect";
         } else {
            const errors = error.response.data.errors || {
               message: [error.response.data.message || errorMessage],
            };
            const finalErrors = Object.values(errors).reduce(
               (accum, next) => [...accum, ...next],
               []
            );
            errorMessage = finalErrors.join("\n");
         }
      }

      setError(errorMessage);
      console.error(error);
   };

   // Extract login success logic
   const handleLoginSuccess = (data) => {
      localStorage.setItem('CURRENT_USER', JSON.stringify(data.user));
      setCurrentUser(data.user);
      setUserToken(data.token, formData.keepSignedIn, data.user);
   };

   // Main submit handler
   const handleSubmit = async (ev) => {
      ev.preventDefault();
      if (uiState.loading) return;
      clearError();
      setLoading(true);

      try {
         const { data } = await axiosClient.post("/login", {
            login: formData.login,
            password: formData.password,
         });
         handleLoginSuccess(data);
      } catch (error) {
         handleLoginError(error);
      } finally {
         setLoading(false);
      }
   };

   return (
      <div className="relative flex flex-col justify-between min-h-screen">


         <motion.div
            className="absolute z-10 top-10 right-10"
            whileHover={{ scale: 1.1 }}
            whileTap={{ scale: 0.9 }}
         >
            <Bulb />
         </motion.div>

         <div className="relative z-10 flex flex-col items-center w-full max-w-lg px-4 mx-auto my-auto">
            <motion.div
               initial={ANIMATIONS.container.initial}
               animate={ANIMATIONS.container.animate}
               className="w-full p-8 bg-white border-0 shadow-xl rounded-2xl backdrop-blur-xl"
            >
               <motion.div
                  initial={ANIMATIONS.logo.initial}
                  animate={ANIMATIONS.logo.animate}
                  className="flex justify-center mb-8"
               >
                  <img
                     src={logo}
                     loading="lazy"
                     alt="AceSurvey Logo"
                     className="w-auto h-32 transition-transform duration-300 hover:scale-105"
                  />
               </motion.div>

               <form onSubmit={handleSubmit} className="space-y-6">
                  <div className="text-center">
                     <h1 className="text-2xl font-bold text-gray-900">Welcome Back</h1>
                     <p className="mt-2 text-sm text-gray-600">Login to your account to continue</p>
                  </div>

                  <ErrorMessage error={uiState.error} onClear={clearError} />

                  <div className="space-y-4">
                     <div>
                        <label htmlFor="username" className="block mb-2 text-sm font-medium text-gray-700">
                           Email or username
                        </label>
                        <input
                           id="username"
                           type="text"
                           placeholder="you@example.com"
                           autoComplete="username"
                           required
                           value={formData.login}
                           onChange={handleInputChange('login')}
                           className={INPUT_CLASS}
                        />
                     </div>

                     <div>
                        <label htmlFor="password" className="block mb-2 text-sm font-medium text-gray-700">
                           Password
                        </label>
                        <div className="relative">
                           <input
                              id="password"
                              autoComplete="current-password"
                              required
                              type={uiState.showPassword ? "text" : "password"}
                              placeholder="Enter your password"
                              value={formData.password}
                              onChange={handleInputChange('password')}
                              className={INPUT_CLASS}
                           />
                           <button
                              type="button"
                              onClick={toggleShowPassword}
                              className="absolute inset-y-0 right-0 flex items-center px-3 text-gray-400 transition-colors hover:text-gray-600"
                              aria-label={uiState.showPassword ? "Hide password" : "Show password"}
                           >
                              {uiState.showPassword ? (
                                 <FaEye className="w-5 h-5" />
                              ) : (
                                 <FaEyeSlash className="w-5 h-5" />
                              )}
                           </button>
                        </div>
                     </div>
                  </div>

                  <div className="flex flex-col space-y-3 sm:flex-row sm:items-center sm:justify-between sm:space-y-0">
                     <label className="flex items-center justify-center sm:justify-start">
                        <input
                           type="checkbox"
                           checked={formData.keepSignedIn}
                           onChange={handleInputChange('keepSignedIn')}
                           className="w-4 h-4 text-blue-600 transition-colors border-2 border-gray-300 rounded focus:ring-blue-500 focus:ring-offset-0"
                        />
                        <span className="ml-2 text-sm text-gray-600">Keep me signed in</span>
                     </label>

                     <div className="text-center sm:text-right">
                        <Link
                           to="/forgot-password"
                           className="text-sm font-medium text-blue-600 transition-colors hover:text-blue-700 hover:underline"
                        >
                           Forgot password?
                        </Link>
                     </div>
                  </div>

                  <motion.button
                     type="submit"
                     disabled={uiState.loading}
                     whileHover={{ scale: 1.01 }}
                     whileTap={{ scale: 0.99 }}
                     className={`flex items-center justify-center w-full gap-2 px-6 py-3 font-medium text-white transition-all duration-200 rounded-lg ${uiState.loading
                        ? "bg-blue-400 cursor-not-allowed"
                        : "bg-blue-600 hover:bg-blue-700 focus:ring-2 focus:ring-blue-500 focus:ring-offset-2"
                        }`}
                  >
                     {uiState.loading ? (
                        <div className="flex items-center gap-2">
                           <RsuiteLoader size="sm" />
                           <span>Signing in...</span>
                        </div>
                     ) : (
                        "Sign in"
                     )}
                  </motion.button>
               </form>
            </motion.div>
         </div>
      </div>
   );
}

import React, { useState, useEffect } from 'react';
import axiosClient from '@api/axios';
import { useParams, useNavigate } from 'react-router-dom'; // Added useNavigate
import { Loader as RsuiteLoader } from 'rsuite';
import 'rsuite/dist/rsuite.min.css';
import logo from '@images/AceLogo.png'; // Adjust path if needed
import { FaEye, FaEyeSlash } from "react-icons/fa";
import AnimatedBackground from "@components/AnimatedBackground";
import { motion } from 'framer-motion';
import ErrorMessage from "@components/ErrorMessage"; // Add this import

const ResetPassword = () => {
   const { token } = useParams();
   const navigate = useNavigate(); // Add navigate hook
   const [email, setEmail] = useState(() => new URLSearchParams(window.location.search).get('email') || '');
   const [password, setPassword] = useState('');
   const [passwordConfirmation, setPasswordConfirmation] = useState('');
   const [message, setMessage] = useState('');
   const [errorMessage, setErrorMessage] = useState(''); // Changed from errors array to errorMessage string
   const [loading, setLoading] = useState(false);
   const [isSuccess, setIsSuccess] = useState(false); // Add success state
   const [showPassword, setShowPassword] = useState(false);
   const [showConfirmPassword, setShowConfirmPassword] = useState(false);

   const toggleShowPassword = () => setShowPassword(!showPassword);
   const toggleShowConfirmPassword = () => setShowConfirmPassword(!showConfirmPassword);

   // Add a function to clear error messages
   const clearErrorMessage = () => {
      setErrorMessage('');
   };

   const handleSubmit = async (e) => {
      e.preventDefault();
      setMessage('');
      setErrorMessage('');
      setLoading(true);

      try {
         const { data } = await axiosClient.post('/reset', {
            token,
            email,
            password,
            password_confirmation: passwordConfirmation,
         });
         setMessage(data.message);
         setIsSuccess(true); // Set success state instead of countdown
      } catch (error) {
         if (error.response && error.response.data.errors) {
            // Convert error array to HTML format for ErrorMessage component
            const allErrors = Object.values(error.response.data.errors).flat();
            setErrorMessage(allErrors.join('\n'));
         } else if (error.response && error.response.data.message) {
            setErrorMessage(error.response.data.message);
         } else {
            setErrorMessage('An unexpected error occurred. Please try again.');
         }
      } finally {
         setLoading(false);
      }
   };

   // If password reset was successful, show success screen
   if (isSuccess) {
      return (
         <div className="relative flex flex-col justify-between min-h-screen bg-gradient-to-br from-blue-50 via-white to-purple-50">
            <AnimatedBackground />
            <motion.div
               initial={{ opacity: 0, y: 20 }}
               animate={{ opacity: 1, y: 0 }}
               className="relative z-10 flex flex-col items-center w-full max-w-lg p-4 mx-auto my-auto"
            >
               <motion.div
                  initial={{ opacity: 0, scale: 0.95 }}
                  animate={{ opacity: 1, scale: 1 }}
                  className="w-full p-8 bg-white shadow-lg rounded-xl backdrop-blur-sm"
               >
                  <motion.div
                     initial={{ y: -20 }}
                     animate={{ y: 0 }}
                     className="flex justify-center mb-6"
                  >
                     <img src={logo} loading="lazy" alt="Logo" className="w-auto h-24 drop-shadow-md" />
                  </motion.div>

                  <div className="flex flex-col items-center justify-center py-6">
                     <div className="flex items-center justify-center w-24 h-24 mb-6 bg-green-100 rounded-full">
                        <svg xmlns="http://www.w3.org/2000/svg" className="w-12 h-12 text-green-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                           <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                        </svg>
                     </div>

                     <h2 className="mb-2 text-2xl font-bold text-center text-gray-900">Password Reset Successful</h2>
                     <p className="max-w-md mb-8 text-center text-gray-600">
                        {message || "Your password has been reset successfully. You can now log in with your new password."}
                     </p>

                     <motion.button
                        onClick={() => navigate('/login')}
                        whileHover={{ scale: 1.01 }}
                        whileTap={{ scale: 0.99 }}
                        className="flex items-center justify-center px-6 py-3 font-medium text-white transition-all duration-200 bg-blue-600 rounded-lg w-44 hover:bg-blue-700"
                     >
                        Go to Login
                     </motion.button>
                  </div>
               </motion.div>
            </motion.div>
         </div>
      );
   }

   return (
      <div className="relative flex flex-col justify-between min-h-screen bg-gradient-to-br from-blue-50 via-white to-purple-50">
         <AnimatedBackground />
         <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="relative z-10 flex flex-col items-center w-full max-w-lg p-4 mx-auto my-auto"
         >
            <motion.div
               initial={{ opacity: 0, scale: 0.95 }}
               animate={{ opacity: 1, scale: 1 }}
               className="w-full p-8 bg-white shadow-lg rounded-xl backdrop-blur-sm"
            >
               <motion.div
                  initial={{ y: -20 }}
                  animate={{ y: 0 }}
                  className="flex justify-center mb-8"
               >
                  <img src={logo} loading="lazy" alt="Logo" className="w-auto h-36 drop-shadow-md" />
               </motion.div>

               <form onSubmit={handleSubmit} className="space-y-6">
                  <h1 className="text-2xl font-bold text-center text-gray-900">
                     Reset Password
                  </h1>

                  {/* Replace the error list with ErrorMessage component */}
                  {errorMessage && (
                     <ErrorMessage error={errorMessage} onClear={clearErrorMessage} />
                  )}

                  <div className="space-y-4">
                     <div className="relative">
                        <label htmlFor="email" className="block mb-1 text-sm font-medium text-gray-700">
                           Email Address
                        </label>
                        <input
                           id="email"
                           type="email"
                           placeholder="Enter your email address"
                           value={email}
                           onChange={(e) => setEmail(e.target.value)}
                           className="w-full px-4 py-3 text-gray-700 transition-colors duration-200 border border-gray-200 rounded-lg bg-gray-50 focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                        />
                     </div>

                     <div className="relative">
                        <label htmlFor="password" className="block mb-1 text-sm font-medium text-gray-700">
                           New Password
                        </label>
                        <div className="relative">
                           <input
                              id="password"
                              type={showPassword ? "text" : "password"}
                              placeholder="Create new password"
                              value={password}
                              onChange={(e) => setPassword(e.target.value)}
                              className="w-full px-4 py-3 text-gray-700 transition-colors duration-200 border border-gray-200 rounded-lg bg-gray-50 focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                           />
                           <button
                              type="button"
                              onClick={toggleShowPassword}
                              className="absolute inset-y-0 right-0 flex items-center px-3 text-gray-400 transition-colors hover:text-gray-600"
                           >
                              {showPassword ? (
                                 <FaEye className="w-5 h-5" />
                              ) : (
                                 <FaEyeSlash className="w-5 h-5" />
                              )}
                           </button>
                        </div>
                     </div>

                     <div className="relative">
                        <label htmlFor="passwordConfirmation" className="block mb-1 text-sm font-medium text-gray-700">
                           Confirm Password
                        </label>
                        <div className="relative">
                           <input
                              id="passwordConfirmation"
                              type={showConfirmPassword ? "text" : "password"}
                              placeholder="Confirm new password"
                              value={passwordConfirmation}
                              onChange={(e) => setPasswordConfirmation(e.target.value)}
                              className="w-full px-4 py-3 text-gray-700 transition-colors duration-200 border border-gray-200 rounded-lg bg-gray-50 focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                           />
                           <button
                              type="button"
                              onClick={toggleShowConfirmPassword}
                              className="absolute inset-y-0 right-0 flex items-center px-3 text-gray-400 transition-colors hover:text-gray-600"
                           >
                              {showConfirmPassword ? (
                                 <FaEye className="w-5 h-5" />
                              ) : (
                                 <FaEyeSlash className="w-5 h-5" />
                              )}
                           </button>
                        </div>
                     </div>
                  </div>

                  <motion.button
                     type="submit"
                     disabled={loading}
                     whileHover={{ scale: 1.01 }}
                     whileTap={{ scale: 0.99 }}
                     className={`
                                w-full px-6 py-3 text-sm font-medium text-white transition-all duration-200 rounded-lg
                                ${loading
                           ? 'bg-blue-400 cursor-not-allowed'
                           : 'bg-blue-600 hover:bg-blue-700 focus:ring-2 focus:ring-blue-500 focus:ring-offset-2'
                        }
                            `}
                  >
                     {loading ? <RsuiteLoader size="sm" /> : 'Reset Password'}
                  </motion.button>
               </form>
            </motion.div>
         </motion.div>
      </div>
   );
};

